-- University: baath
with univ as (select id from public.universities where slug = 'baath')
insert into public.colleges (university_id, name_ar, name_en, slug, is_active)
select univ.id, v.name_ar, v.name_en, v.slug, true from (values
  ('الطب البشري', 'Human Medicine', 'baath-medicine'),
  ('طب الأسنان', 'Dentistry', 'baath-dentistry'),
  ('الصيدلة', 'Pharmacy', 'baath-pharmacy'),
  ('الهندسة', 'Engineering', 'baath-engineering'),
  ('العلوم', 'Science', 'baath-science'),
  ('الاقتصاد', 'Economics', 'baath-economics'),
  ('الحقوق', 'Law', 'baath-law'),
  ('الآداب والعلوم الإنسانية', 'Arts and Humanities', 'baath-arts-humanities'),
  ('التربية', 'Education', 'baath-education'),
